<template>
  <a-modal :open="true" :width="1260" centered :footer="null" :mask-closable="false" :title="id ? t('rooms.form.editTitle') : t('rooms.form.createTitle')" class="room-editor-modal" @cancel="close">
    <a-spin :spinning="loading || uploading">
      <a-alert v-if="error" type="error" :message="error" show-icon />
      <template v-if="ready">
        <div class="status-line"><strong>{{ tr('Room Type Status', '房型销售状态') }}</strong><a-switch v-model:checked="enabled" :disabled="!canChangeStatus" /></div>
        <nav class="steps" :aria-label="tr('Room setup steps', '客房设置步骤')"><button v-for="(label, i) in steps" :key="label" type="button" :class="{ active: step === i, complete: step > i }" :aria-current="step === i ? 'step' : undefined" @click="step = i"><span>{{ i + 1 }}</span>{{ label }}</button></nav>
        <div class="editor-scroll">
          <a-form layout="vertical">
            <div v-show="step === 0">
              <div class="two-grid"><a-form-item :label="t('rooms.form.hotel')" required><a-select :value="draft.property_id || undefined" :disabled="!!id" @change="changeProperty"><a-select-option v-for="hotel in hotels" :key="hotel.id" :value="hotel.id">{{ hotel.property_name }}</a-select-option></a-select></a-form-item><a-form-item :label="t('rooms.fields.roomName')" required><a-input v-model:value="draft.room_name" :maxlength="100" :placeholder="t('rooms.placeholders.roomName')" /></a-form-item></div>
              <div class="two-grid"><a-form-item :label="tr('Base Price (per night)', '基础价格（每晚）')" required><a-input-number v-model:value="draft.base_price" :min="0" :precision="2" :addon-after="draft.currency" /></a-form-item><a-form-item :label="tr('Weekend Price (per night)', '周末价格（每晚）')"><a-input-number v-model:value="draft.weekend_price" :min="0" :precision="2" :addon-after="draft.currency" /></a-form-item></div>
              <p class="note">{{ tr('Currency is set by your merchant site. Weekend: Friday and Saturday; 0 uses the base price.', '币种由商户所属站点确定。周末为周五、周六；周末价为 0 时使用基础价。') }}</p>
              <div class="three-grid"><a-form-item :label="tr('Max Guests', '最多入住人数')" required><a-input-number v-model:value="draft.max_guests" :min="1" :precision="0" /></a-form-item><a-form-item :label="tr('Room Size', '客房面积')" required><div class="size-input"><a-input-number v-model:value="displayArea" :min="0" :precision="2" /><a-select :value="draft.area_unit" @change="changeUnit"><a-select-option value="sqm">sqm</a-select-option><a-select-option value="sqft">sqFt</a-select-option></a-select></div></a-form-item><a-form-item :label="tr('Room Quantity', '客房总数')" required><a-input-number v-model:value="draft.base_stock" :min="0" :precision="0" /></a-form-item></div>
              <section class="editor-section"><div class="section-title"><h3>{{ tr('Bedding Setup', '床型配置') }}</h3><a-button :disabled="draft.bedding.length >= 20" @click="draft.bedding.push({ id: uid(), type: '', quantity: 1 })"><PlusOutlined />{{ tr('Add Bed', '添加床型') }}</a-button></div><div v-for="(bed, i) in draft.bedding" :key="bed.id" class="bed-row"><a-form-item :label="t('rooms.fields.bedType')"><a-auto-complete v-model:value="bed.type" :options="bedTypes.map(value => ({ value }))" :placeholder="tr('Select bed type', '选择床型')" /></a-form-item><a-form-item :label="tr('Quantity', '数量')"><a-input-number v-model:value="bed.quantity" :min="1" :max="100" :precision="0" /></a-form-item><a-button :aria-label="tr('Delete bed', '删除床型')" :disabled="draft.bedding.length === 1" @click="draft.bedding.splice(i, 1)"><DeleteOutlined /></a-button></div></section>
              <a-form-item :label="tr('Room Amenities', '客房设施')"><a-select v-model:value="draft.facilities" mode="multiple" :options="amenityOptions" :placeholder="tr('Select room amenities', '选择客房设施')" /><div class="selected-amenities"><span v-for="item in draft.facilities" :key="item"><WifiOutlined v-if="item === 'wifi' || item === 'WiFi'" /><CheckCircleOutlined v-else />{{ amenityLabels[item] ? tr(...amenityLabels[item]!) : item }}</span></div></a-form-item>
              <div class="status-line"><strong>{{ tr('Breakfast Included', '包含早餐') }}</strong><a-switch :checked="draft.breakfast > 0" @change="changeBreakfast" /></div>
              <a-collapse ghost class="supplement"><a-collapse-panel key="more" :header="tr('Additional Room Information & Policies', '补充客房资料及政策')"><div class="two-grid"><a-form-item :label="t('rooms.fields.roomCode')"><a-input v-model:value="draft.room_code" :maxlength="50" /></a-form-item><a-form-item :label="tr('Default Sellable Quota', '默认可售配额')"><a-input-number v-model:value="draft.launch_stock" :min="0" :max="draft.base_stock" :precision="0" /></a-form-item><a-form-item :label="t('rooms.fields.maxAdults')"><a-input-number v-model:value="draft.max_adults" :min="1" :max="draft.max_guests" :precision="0" /></a-form-item><a-form-item :label="t('rooms.fields.maxChildren')"><a-input-number v-model:value="draft.max_children" :min="0" :max="draft.max_guests" :precision="0" /></a-form-item><a-form-item :label="t('rooms.fields.floorName')"><a-input v-model:value="draft.floor_name" :maxlength="50" /></a-form-item><a-form-item :label="t('rooms.fields.roomView')"><a-input v-model:value="draft.room_view" :maxlength="80" /></a-form-item><a-form-item :label="t('rooms.fields.smoking')"><a-switch :checked="draft.smoking === 1" @change="changeSmoking" /></a-form-item><a-form-item :label="t('rooms.fields.extraBedPrice')"><a-input-number v-model:value="draft.extra_bed_price" :min="0" :precision="2" :addon-after="draft.currency" /></a-form-item><a-form-item :label="t('rooms.fields.mealPlan')"><a-select v-model:value="draft.meal_plan" :options="mealOptions" @change="syncBreakfast" /></a-form-item><a-form-item :label="tr('Sort Order', '排序值')"><a-input-number v-model:value="draft.sort" :precision="0" /></a-form-item></div><p class="note">{{ tr('The default quota applies only to dates without an inventory override. Existing daily inventory stays unchanged.', '默认配额仅用于未单独设置库存的日期，不覆盖已有日库存。') }}</p><a-form-item :label="t('rooms.fields.description')"><a-textarea v-model:value="draft.description" :rows="3" :maxlength="1000" show-count /></a-form-item>
              <a-form-item :label="t('rooms.fields.cancellationPolicy')"><a-select v-model:value="policyMode" :options="policyOptions" @change="selectPolicy" /></a-form-item><a-alert v-if="policyMode === 0" :message="tr('Keep the existing executable policy. Legacy text does not change refund calculations.', '沿用当前可执行政策，历史文案不改变退款计算。')" type="info" /><p v-if="draft.cancellation_policy">{{ draft.cancellation_policy }}</p><template v-if="draft.refund_policy"><div v-if="draft.refund_policy.ruleType === 2"><div v-for="(rule, i) in draft.refund_policy.rules" :key="i" class="refund-row"><a-input-number v-model:value="rule.hours_before" :min="0" :precision="0" :addon-after="tr('hours before check-in', '入住前小时')" /><a-input-number v-model:value="rule.refund_rate" :min="0" :max="100" addon-after="%" /><a-button :aria-label="tr('Delete rule', '删除规则')" @click="draft.refund_policy.rules.splice(i, 1)"><DeleteOutlined /></a-button></div><a-button @click="draft.refund_policy.rules.push({ hours_before: 24, refund_rate: 100 })">{{ tr('Add refund tier', '添加退款阶梯') }}</a-button></div><a-form-item :label="tr('Policy description', '政策说明')"><a-textarea v-model:value="draft.refund_policy.remark" :maxlength="500" /></a-form-item></template><a-form-item :label="t('rooms.fields.checkinNotes')"><a-textarea v-model:value="draft.checkin_notes" :rows="3" :maxlength="500" /></a-form-item></a-collapse-panel></a-collapse>
            </div>
            <div v-show="step === 1"><h3>{{ tr('Room Images', '客房图片') }}</h3><p class="note">{{ t('rooms.media.rules') }}</p><div class="image-grid"><article v-for="(photo, i) in draft.image_gallery" :key="photo.url" class="image-card"><a-image :src="photo.url" :alt="draft.room_name" /><span v-if="i === 0" class="cover-label">{{ t('rooms.media.cover') }}</span><div class="image-tools"><a-button size="small" :disabled="i === 0" :aria-label="tr('Move earlier', '向前移动')" @click="moveImage(i, -1)"><ArrowLeftOutlined /></a-button><a-button size="small" :disabled="i === draft.image_gallery.length - 1" :aria-label="tr('Move later', '向后移动')" @click="moveImage(i, 1)"><ArrowRightOutlined /></a-button><a-button size="small" danger :aria-label="tr('Delete image', '删除图片')" @click="draft.image_gallery.splice(i, 1)"><DeleteOutlined /></a-button></div><a-select v-model:value="photo.category" :options="imageCategories" /><div class="image-links"><a-button type="link" size="small" :disabled="i === 0" @click="makeCover(i)">{{ t('rooms.media.setCover') }}</a-button><a-button type="link" size="small" @click="pick('image', i)">{{ tr('Replace', '替换') }}</a-button></div></article><button v-if="draft.image_gallery.length < 10" type="button" class="upload-slot" @dragover.prevent @drop.prevent="dropFiles($event, 'image')" @click="pick('image')"><PlusOutlined /><span>{{ tr('Add New', '添加图片') }}</span></button></div><section class="editor-section"><h3>{{ tr('Room Video (optional)', '客房视频（选填）') }}</h3><video v-if="draft.video_url" :src="draft.video_url" controls /><a-space><a-button @click="pick('video')"><UploadOutlined />{{ t('rooms.media.uploadVideo') }}</a-button><a-button v-if="draft.video_url" danger @click="draft.video_url = ''">{{ t('common.delete') }}</a-button></a-space></section></div>
            <div v-show="step === 2"><h3>{{ tr('Room Media & Interactive Views', '客房媒体及交互视图') }}</h3><p class="note">{{ tr('Manage virtual tours and immersive room views.', '管理虚拟导览与沉浸式客房全景。') }}</p><section class="editor-section"><div class="section-title"><h3>{{ tr('Local 360° Panorama', '本地 360° 全景') }}</h3><a-switch v-model:checked="draft.panorama.enabled" /></div><p class="note">{{ tr('Equirectangular JPG/PNG/WEBP · 2:1 · minimum 1600×800 · maximum 25MB', '等距柱状投影 JPG/PNG/WEBP · 2:1 · 最低 1600×800 · 最大 25MB') }}</p><RoomPanorama v-if="draft.panorama.url && step === 2" :src="draft.panorama.url" :hint="tr('Drag to look around · Scroll to zoom', '拖动查看全景，滚动缩放')" /><a-space class="media-buttons"><a-button @click="pick('panorama')"><UploadOutlined />{{ tr('Upload 360° Image', '上传全景图') }}</a-button><a-button v-if="draft.panorama.url" danger @click="draft.panorama = { enabled: false, url: '' }">{{ t('common.delete') }}</a-button></a-space></section><section class="editor-section"><div class="section-title"><h3>{{ tr('VR Tour (External Provider)', 'VR 导览（外部服务商）') }}</h3><a-switch :checked="false" disabled /></div><a-alert :message="tr('Provider not connected. Save your configuration now; activation will be available after integration.', '服务商尚未接入。可先保存配置，接入后再开放启用。')" type="info" show-icon /><a-form-item :label="tr('VR Tour URL', 'VR 导览地址')"><a-input v-model:value="draft.vr_tour.url" placeholder="https://" :maxlength="2000" /></a-form-item><a-form-item :label="tr('VR Cover Image', 'VR 封面图片')"><a-image v-if="draft.vr_tour.cover" :src="draft.vr_tour.cover" :width="240" /><button type="button" class="upload-wide" @dragover.prevent @drop.prevent="dropFiles($event, 'vr_cover')" @click="pick('vr_cover')"><UploadOutlined />{{ tr('Upload cover · 4:3 · maximum 25MB', '上传封面 · 4:3 · 最大 25MB') }}</button><a-button v-if="draft.vr_tour.cover" type="link" danger @click="draft.vr_tour.cover = ''">{{ t('common.delete') }}</a-button></a-form-item></section></div>
            <div v-show="step === 3"><h3>{{ tr('Room Media & Interactive Views', '客房媒体及交互视图') }}</h3><p class="note">{{ tr('Manage gallery images, virtual tours, and interactive floor plans.', '管理图库、虚拟导览与交互平面图。') }}</p><section class="editor-section"><div class="section-title"><div><h3>{{ tr('3D Floor Plan (Interactive Tool)', '交互平面图') }}</h3><p class="note">{{ tr('Help guests explore the room layout.', '帮助客人了解客房布局。') }}</p></div><a-switch v-model:checked="draft.floor_plan.enabled" /></div><div class="base-upload"><div><strong>{{ tr('Base Floor Plan', '基础平面图') }}</strong><p class="note">{{ tr('Select a pin, then click the image to position it.', '选择热点后，点击图片调整该热点位置。') }}</p></div><a-button @click="pick('floorplan')"><UploadOutlined />{{ tr('Upload Base Floor Plan Image', '上传平面图') }}</a-button></div><RoomFloorPlan v-if="draft.floor_plan.image" :image="draft.floor_plan.image" :hotspots="draft.floor_plan.hotspots" editing :selected="selectedPin" @position="positionPin" @select="selectedPin = $event" /><a-button v-if="draft.floor_plan.image" type="link" danger @click="clearFloor">{{ tr('Remove floor plan', '移除平面图') }}</a-button><div class="hotspot-panel"><div class="section-title"><h3>{{ tr('Hotspot Editor Panel', '热点编辑面板') }}</h3><a-button type="primary" :disabled="!draft.floor_plan.image || draft.floor_plan.hotspots.length >= 50" @click="addPin"><PlusOutlined />{{ tr('Add New Pin', '新增热点') }}</a-button></div><a-radio-group v-model:value="selectedPin" class="pin-tabs"><a-radio-button v-for="(pin, i) in draft.floor_plan.hotspots" :key="pin.id" :value="pin.id">{{ i + 1 }}. {{ pin.title || tr('Pin', '热点') }}</a-radio-button></a-radio-group><div v-if="pin" class="pin-form"><div class="two-grid"><a-form-item :label="tr('Pin Title', '热点标题')"><a-input v-model:value="pin.title" :maxlength="80" /></a-form-item><a-form-item :label="tr('Short Description', '简短说明')"><a-textarea v-model:value="pin.description" :maxlength="500" :rows="2" /></a-form-item></div><a-form-item :label="tr('Attach Close-up Image', '添加特写图片')"><a-image v-if="pin.image" :src="pin.image" :width="160" /><button type="button" class="upload-wide" @dragover.prevent @drop.prevent="dropFiles($event, 'closeup')" @click="pick('closeup')"><UploadOutlined />{{ tr('Browse files', '选择文件') }}</button><a-button v-if="pin.image" type="link" danger @click="pin.image = ''">{{ tr('Remove image', '移除图片') }}</a-button></a-form-item><a-button danger @click="deletePin">{{ tr('Delete Pin', '删除热点') }}</a-button></div><a-empty v-else :description="tr('Add a pin to describe a place in the room.', '添加热点说明客房中的位置。')" /></div></section></div>
          </a-form>
        </div>
        <footer class="editor-footer"><a-space><a-button @click="step > 0 ? step-- : close()">{{ step > 0 ? tr('Previous', '上一步') : t('common.cancel') }}</a-button><a-button @click="preview = true"><EyeOutlined />{{ tr('Preview', '预览') }}</a-button></a-space><a-space><a-button v-perm="id ? 'mch:rooms:edit' : 'mch:rooms:add'" :loading="saving" :disabled="uploading" @click="save(false)">{{ t('rooms.actions.saveDraft') }}</a-button><a-button v-if="step < 3" type="primary" @click="next">{{ tr('Next Step', '下一步') }}<ArrowRightOutlined /></a-button><a-button v-else v-perm="id ? 'mch:rooms:edit' : 'mch:rooms:add'" type="primary" :loading="saving" :disabled="uploading" @click="save(true)">{{ t('rooms.actions.submitReview') }}</a-button></a-space></footer>
      </template>
      <a-button v-else-if="!loading" @click="load">{{ tr('Retry', '重试') }}</a-button>
    </a-spin>
    <input ref="fileInput" hidden type="file" :accept="uploadKind === 'video' ? 'video/mp4,video/quicktime' : 'image/jpeg,image/png,image/webp'" :multiple="uploadKind === 'image' && replaceIndex < 0" @change="upload" />
    <a-modal v-model:open="preview" :width="1000" :title="tr('Unsaved Preview', '未保存预览')" :footer="null"><RoomSnapshot :room="snapshot" /></a-modal>
  </a-modal>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue';
import { message, Modal } from 'ant-design-vue';
import { onBeforeRouteLeave } from 'vue-router';
import { useI18n } from 'vue-i18n';
import { ArrowLeftOutlined, ArrowRightOutlined, CheckCircleOutlined, DeleteOutlined, EyeOutlined, PlusOutlined, UploadOutlined, WifiOutlined } from '@ant-design/icons-vue';
import { apiRoomDetail, apiRoomHotels, apiRoomSave, apiRoomUpload, type RoomHotelOption, type Bedding, type RoomImage, type Hotspot, type RefundPolicy, type MediaKind } from '@/api/rooms';
import { useUserStore } from '@/stores/user';
import { amenityLabels, roomAmenities, useRoomText } from '../presentation';
import RoomSnapshot from './RoomSnapshot.vue';
import RoomPanorama from './RoomPanorama.vue';
import RoomFloorPlan from './RoomFloorPlan.vue';
const props = withDefaults(defineProps<{ id?: number; propertyId?: number }>(), { id: 0, propertyId: 0 });
const emit = defineEmits<{ close: []; saved: [id: number, propertyId: number] }>(); const tr = useRoomText(); const { t } = useI18n(); const user = useUserStore();
const step = ref(0); const loading = ref(false); const saving = ref(false); const uploading = ref(false); const error = ref(''); const ready = ref(false); const preview = ref(false); const hotels = ref<RoomHotelOption[]>([]); const fileInput = ref<HTMLInputElement>(); const uploadKind = ref<MediaKind>('image'); const replaceIndex = ref(-1); const selectedPin = ref(''); const policyMode = ref(0); let baseline = ''; let active = true;
const uid = () => crypto.randomUUID();
const draft = reactive({ property_id: props.propertyId, room_name: '', room_code: '', description: '', bed_type: '', bed_count: 1, bedding: [{ id: uid(), type: '', quantity: 1 }] as Bedding[], area: '', area_unit: 'sqm' as 'sqm' | 'sqft', max_adults: 2, max_children: 0, max_guests: 2, floor_name: '', room_view: '', smoking: 0, breakfast: 0, meal_plan: 'room_only', cancellation_policy: '', currency: '', checkin_notes: '', base_price: 0, weekend_price: 0, extra_bed_price: 0, base_stock: 0, launch_stock: 0, images: [] as string[], image_gallery: [] as RoomImage[], video_url: '', facilities: [] as string[], status: 1, sort: 0, panorama: { enabled: false, url: '' }, vr_tour: { enabled: false, url: '', cover: '' }, floor_plan: { enabled: false, image: '', hotspots: [] as Hotspot[] }, refund_policy: null as RefundPolicy | null });
// 默认可售配额留空(=0)等于"没有配额":客房总数变化时把尚未设置/仍在跟随的配额同步过来,
// 否则表单上会留一个 0,商户以为可售数为 0(后端 RoomDefaults::stock 也会把 0 视为未设置回退)。
// 商户显式填过的更小配额不覆盖(判断"仍是上一个客房总数"说明还在跟随)。
watch(() => draft.base_stock, (value, previous) => { if (!Number(draft.launch_stock) || Number(draft.launch_stock) === Number(previous)) draft.launch_stock = Math.max(0, Number(value) || 0); });
const enabled = computed({ get: () => draft.status === 1, set: value => { draft.status = value ? 1 : 2; } });
const canChangeStatus = computed(() => !props.id || user.hasPerm('mch:rooms:status'));
const displayArea = computed({ get: () => draft.area ? Number((Number(draft.area) / (draft.area_unit === 'sqft' ? .09290304 : 1)).toFixed(2)) : null, set: value => { draft.area = value == null ? '' : String(Number(value) * (draft.area_unit === 'sqft' ? .09290304 : 1)); } });
const steps = computed(() => [tr('Room Information', '客房信息'), tr('Room Images', '客房图片'), tr('VR Tour', 'VR 导览'), tr('3D Floor Plan', '交互平面图')]);
const bedTypes = ['King', 'Queen', 'Double', 'Single', 'Twin', 'Sofa Bed', 'Bunk Bed'];
const amenityOptions = computed(() => [...new Set([...roomAmenities, ...draft.facilities])].map(value => ({ value, label: amenityLabels[value] ? tr(...amenityLabels[value]!) : value })));
const imageCategories = computed(() => [{ value: 'bedroom', label: tr('Bedroom', '卧室') }, { value: 'bathroom', label: tr('Bathroom', '浴室') }, { value: 'view', label: tr('View', '景观') }, { value: 'other', label: tr('Other', '其他') }]);
const mealOptions = computed(() => { const options = ['room_only', 'breakfast', 'half_board', 'full_board', 'all_inclusive'].map((value, i) => ({ value, label: [t('rooms.meal.roomOnly'), t('rooms.meal.breakfast'), t('rooms.meal.halfBoard'), t('rooms.meal.fullBoard'), t('rooms.meal.allInclusive')][i] })); if (draft.meal_plan && !options.some(o => o.value === draft.meal_plan)) options.push({ value: draft.meal_plan, label: draft.meal_plan }); return options; });
const policyOptions = computed(() => [{ value: 0, label: tr('Keep current policy', '沿用当前政策') }, { value: 1, label: tr('Free cancellation', '免费取消') }, { value: 2, label: tr('Tiered refund', '阶梯退款') }, { value: 3, label: tr('Non-refundable', '不可退款') }]);
const pin = computed(() => draft.floor_plan.hotspots.find(p => p.id === selectedPin.value));
const snapshot = computed(() => ({ ...draft, images: draft.image_gallery.map(i => i.url), refund_policy: draft.refund_policy || undefined }));
function changeUnit(unit: 'sqm' | 'sqft') { draft.area_unit = unit; }
function changeBreakfast(value: boolean | string | number) { draft.breakfast = value ? 1 : 0; draft.meal_plan = value ? 'breakfast' : 'room_only'; }
function changeSmoking(value: boolean | string | number) { draft.smoking = value ? 1 : 0; }
function syncBreakfast() { if (['room_only', 'breakfast', 'half_board', 'full_board', 'all_inclusive'].includes(draft.meal_plan)) draft.breakfast = draft.meal_plan === 'room_only' ? 0 : 1; }
function selectPolicy(value: number) { draft.refund_policy = value ? { ruleType: value, rules: value === 2 ? [{ hours_before: 0, refund_rate: 0 }] : [], remark: '' } : null; }
async function confirmChange(title: string) { return new Promise<boolean>(resolve => Modal.confirm({ title, onOk: () => resolve(true), onCancel: () => resolve(false) })); }
async function changeProperty(value: number) { if (value === draft.property_id) return; if (dirty() && !await confirmChange(tr('Change hotel? Uploaded media and policy will be cleared.', '切换酒店将清空已上传媒体与政策，是否继续？'))) return; draft.property_id = value; draft.currency = hotels.value.find(h => h.id === value)?.currency || ''; draft.image_gallery = []; draft.video_url = ''; draft.panorama = { enabled: false, url: '' }; draft.vr_tour = { enabled: false, url: '', cover: '' }; draft.floor_plan = { enabled: false, image: '', hotspots: [] }; draft.refund_policy = null; policyMode.value = 0; }
function dirty() { return ready.value && JSON.stringify(draft) !== baseline; }
async function close() { if (saving.value || uploading.value) return; if (dirty() && !await confirmChange(tr('Discard unsaved changes?', '放弃未保存的修改？'))) return; baseline = JSON.stringify(draft); emit('close'); }
function beforeUnload(e: BeforeUnloadEvent) { if (dirty()) { e.preventDefault(); e.returnValue = ''; } }
function moveImage(i: number, delta: number) { const moved = draft.image_gallery.splice(i, 1)[0]!; draft.image_gallery.splice(i + delta, 0, moved); }
function makeCover(i: number) { draft.image_gallery.unshift(draft.image_gallery.splice(i, 1)[0]!); }
function pick(kind: MediaKind, index = -1) { if (!draft.property_id) { message.warning(tr('Select a hotel first', '请先选择酒店')); return; } uploadKind.value = kind; replaceIndex.value = index; setTimeout(() => fileInput.value?.click(), 0); }
async function upload(e: Event) { const input = e.target as HTMLInputElement; try { await uploadFiles(Array.from(input.files || []), uploadKind.value); } finally { input.value = ''; } }
function dropFiles(e: DragEvent, kind: MediaKind) { replaceIndex.value = -1; void uploadFiles(Array.from(e.dataTransfer?.files || []), kind); }
async function uploadFiles(files: File[], kind: MediaKind) { if (uploading.value || !draft.property_id) return; if (kind !== 'image') files = files.slice(0, 1); const propertyId = draft.property_id; const targetPin = pin.value; uploading.value = true; try { if (kind === 'image' && replaceIndex.value < 0 && draft.image_gallery.length + files.length > 10) { message.warning(tr('Maximum 10 room images', '客房图片最多 10 张')); return; } for (const file of files) { const result = await apiRoomUpload(file, kind, propertyId, props.id); if (!active || propertyId !== draft.property_id) return; if (kind === 'image') { const photo = { url: result.url, category: 'bedroom' as const }; if (replaceIndex.value >= 0) { photo.category = draft.image_gallery[replaceIndex.value]!.category as 'bedroom'; draft.image_gallery.splice(replaceIndex.value, 1, photo); } else draft.image_gallery.push(photo); } else if (kind === 'video') draft.video_url = result.url; else if (kind === 'panorama') draft.panorama.url = result.url; else if (kind === 'vr_cover') draft.vr_tour.cover = result.url; else if (kind === 'closeup' && targetPin) targetPin.image = result.url; else if (kind === 'floorplan') { if (draft.floor_plan.hotspots.length && !await confirmChange(tr('Replace floor plan and reset all pins?', '替换平面图并重置全部热点？'))) return; draft.floor_plan.image = result.url; draft.floor_plan.hotspots = []; selectedPin.value = ''; } } } finally { uploading.value = false; } }
function addPin() { const item = { id: uid(), x: .5, y: .5, title: '', description: '', image: '' }; draft.floor_plan.hotspots.push(item); selectedPin.value = item.id; }
function positionPin(x: number, y: number) { if (!pin.value) addPin(); if (pin.value) { pin.value.x = x; pin.value.y = y; } }
function deletePin() { draft.floor_plan.hotspots = draft.floor_plan.hotspots.filter(p => p.id !== selectedPin.value); selectedPin.value = draft.floor_plan.hotspots[0]?.id || ''; }
async function clearFloor() { if (!await confirmChange(tr('Remove floor plan and its pins?', '移除平面图及全部热点？'))) return; draft.floor_plan = { enabled: false, image: '', hotspots: [] }; }
function validBasics(submit: boolean) { if (!draft.property_id || !draft.room_name.trim()) { message.warning(t('rooms.form.requiredTip')); step.value = 0; return false; } if (submit && Number(draft.base_stock) > 0 && Number(draft.launch_stock) <= 0) { message.warning(tr('The default sellable quota must be greater than 0, otherwise this room type cannot be sold.', '默认可售配额需大于 0，否则该房型无法售出。')); step.value = 0; return false; } if (submit && (!Number(draft.area) || draft.bedding.some(b => !b.type.trim() || !b.quantity) || draft.max_guests < Math.max(draft.max_adults, draft.max_children) || draft.launch_stock > draft.base_stock)) { message.warning(tr('Check bedding, room size, capacity and sellable quota.', '请检查床型、面积、人数与可售配额。')); step.value = 0; return false; } return true; }
function next() { if (step.value === 0 && !validBasics(true)) return; step.value++; }
async function save(submit: boolean) { if (saving.value || uploading.value || !validBasics(submit)) return; if (submit && !draft.image_gallery.length) { message.warning(t('rooms.media.photoRequired')); step.value = 1; return; } saving.value = true; try { const data = Object.fromEntries(Object.entries(draft).map(([key, value]) => [key.replace(/_([a-z])/g, (_, c: string) => c.toUpperCase()), value])); data.bedding = draft.bedding.filter(b => b.type.trim()); data.area = draft.area ? String(Number(Number(draft.area).toFixed(6))) : ''; const result = await apiRoomSave({ ...data, id: props.id || undefined, publishStatus: submit ? 1 : 0 }); baseline = JSON.stringify(draft); message.success(submit ? t('rooms.messages.submitted') : t('rooms.messages.draftSaved')); emit('saved', result.id, draft.property_id); } finally { saving.value = false; } }
async function load() { loading.value = true; error.value = ''; try { hotels.value = await apiRoomHotels(); if (props.id) { const detail = await apiRoomDetail(props.id, props.propertyId); if (detail.latestRevision?.status === 1) { error.value = t('rooms.messages.pendingLocked'); return; } const row = { ...detail.room, ...detail.editable }; Object.keys(draft).forEach(key => { if (row[key as keyof typeof row] != null) (draft as Record<string, unknown>)[key] = row[key as keyof typeof row]; }); for (const key of ['base_price', 'weekend_price', 'extra_bed_price', 'base_stock', 'launch_stock', 'max_adults', 'max_children', 'max_guests', 'sort'] as const) draft[key] = Number(draft[key]); draft.bedding = row.bedding?.length ? row.bedding : [{ id: uid(), type: row.bed_type || '', quantity: row.bed_count || 1 }]; draft.image_gallery = row.image_gallery?.length ? row.image_gallery : (row.images || []).map(url => ({ url, category: 'bedroom' })); draft.panorama = { enabled: false, url: '', ...row.panorama }; draft.vr_tour = { enabled: false, url: '', cover: '', ...row.vr_tour }; draft.floor_plan = { enabled: false, image: '', hotspots: [], ...row.floor_plan }; draft.refund_policy = row.refund_policy?.ruleType ? row.refund_policy : null; policyMode.value = draft.refund_policy?.ruleType || 0; selectedPin.value = draft.floor_plan.hotspots[0]?.id || ''; } else { draft.property_id = props.propertyId || user.selectedPropertyId || (hotels.value.length === 1 ? hotels.value[0]!.id : 0); draft.currency = hotels.value.find(h => h.id === draft.property_id)?.currency || ''; } if (Number(draft.launch_stock) <= 0) draft.launch_stock = Math.max(0, Number(draft.base_stock) || 0); ready.value = true; baseline = JSON.stringify(draft); } catch { error.value = tr('Room data could not be loaded.', '客房资料加载失败。'); } finally { loading.value = false; } }
watch(() => user.selectedPropertyId, async () => { if (!dirty() || await confirmChange(tr('Property changed. Close this editor and discard changes?', '全局物业已切换，关闭编辑并放弃未保存修改？'))) emit('close'); });
onMounted(() => { void load(); window.addEventListener('beforeunload', beforeUnload); });
onBeforeRouteLeave(async () => { if (uploading.value || saving.value) return false; return !dirty() || await confirmChange(tr('Discard unsaved changes?', '放弃未保存的修改？')); });
onBeforeUnmount(() => { active = false; window.removeEventListener('beforeunload', beforeUnload); });
</script>
